{"ts":"2026-09-19T21:18:11.724+03:00","v":"1","level":"DEBUG","logger":"org.hibernate.SQL","thread":"Test worker","msg":"SELECT a.*
FROM assignments a
JOIN semesters existing_semester ON existing_semester.id = a.semester_id
WHERE a.teacher_id = ?
