        '[)'
      ) && daterange(
        CAST(? AS date),
        COALESCE(CAST(? AS date), existing_semester.date_to + 1),
        '[)'
      )
LIMIT 1
","traceId":"cedc845074e30c76bc3f60d6170316e7","service":"academic-service"}
